    capability Checkout {
      actor Ref<User>;
      input CheckoutInput;
      output OrderView;
      fails CartEmpty;
      fails CartTooLarge;
      fails OutOfStock;
      requires authenticated;
      requires atomic;
      expose command at "/cart/checkout";
      workflow {
        count CartItem where item.owner == actor as total;
        validate total > 0 else CartEmpty;
        validate total <= 50 else CartTooLarge;
        create PurchaseOrder as made { buyer: actor; state: OrderState.CREATED; total: 0.00; createdAt: now(); }
        persist made;
        each CartItem where item.owner == actor order by id ascending limit 50 else CartTooLarge as row {
          load ShopProduct by row.product as goods for update else ProductNotFound;
          validate goods.state == ProductState.ON_SHELF else ProductNotFound;
          update goods when goods.stock >= row.quantity else OutOfStock { stock: goods.stock - row.quantity; }
          persist goods;
          create OrderLine as line { purchase: made; product: goods; quantity: row.quantity; unitPrice: goods.price; }
          persist line;
          update made { total: made.total + goods.price * row.quantity; }
          delete row;
        }
        persist made;
        return made;
      }
    }

    capability AddCoupon {
