      input RegisterInput;
      output UserView;
      fails Missing;
      requires atomic;
      expose command at "/register";
      workflow {
        validate input.name is present else Missing;
        exists User where item.name == input.name as found;
        validate not found else Missing;
        create User as made { name: input.name; passwordHash: input.password; role: Role.CUSTOMER; }
        persist made;
        return made;
      }
    }

    capability Login {
      input LoginInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/login";
      workflow {
        load User by name: input.name as account else Missing;
        validate account.passwordHash matches input.password else Missing;
        create AccessToken as access { owner: account; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: account; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

    capability Refresh {
      input RefreshInput;
      output TokenPair;
      fails Missing;
      requires atomic;
      expose command at "/refresh";
      workflow {
        load RefreshToken by input.refreshToken as stored else Missing;
        validate stored.used == false else Missing;
        validate stored.expiresAt > now() else Missing;
        update stored { used: true; }
        persist stored;
        create AccessToken as access { owner: stored.owner; expiresAt: now() + 15 minutes; }
        persist access;
        create RefreshToken as refresh { owner: stored.owner; used: false; expiresAt: now() + 7 days; }
        persist refresh;
        create TokenPair as pair { accessToken: access.id; accessExpiresAt: access.expiresAt; refreshToken: refresh.id; refreshExpiresAt: refresh.expiresAt; }
        persist pair;
        return pair;
      }
    }

